test('lateFee: returns 0 for invoices not yet due', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  // Invoice due date is 2025-03-16, check on 2025-03-15 (one day before)
  const result = lateFee(invoice, '2025-03-15');

  assert.equal(result, 0);
});

test('lateFee: returns 0 for invoices due on asOf date', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  // Check on the due date itself
  const result = lateFee(invoice, invoice.dueDate);

  assert.equal(result, 0);
});

test('lateFee: calculates fee for 1 day overdue', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  // Due date is 2025-03-16, check 1 day later = 2025-03-17
  // Amount due: 95000 (DEV-HOUR: 9500 * 10, no discount for standard tier)
  // VAT: 19950
  // Total: 114950
  // Fee: 114950 * 0.0004 * 1 = 45.98 ≈ 46 cents
  const result = lateFee(invoice, '2025-03-17');

  assert.equal(result, 46);
});

test('lateFee: calculates fee for multiple days overdue', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  // Due date is 2025-03-16, check 10 days later = 2025-03-26
  // Amount due: 114950
  // Fee: 114950 * 0.0004 * 10 = 459.8 ≈ 460 cents
  const result = lateFee(invoice, '2025-03-26');

  assert.equal(result, 460);
});

test('lateFee: applies to partially paid invoices', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  let invoice = issueInvoice(invoiceResult.value, []).value;

  const paymentResult = recordPayment(invoice, { amount: 50000, date: '2025-03-01' });
  assert.equal(paymentResult.ok, true);
  invoice = paymentResult.value;

  // Due: 114950 - 50000 = 64950
  // Days overdue: from 2025-03-16 to 2025-03-26 = 10 days
  // Fee: 64950 * 0.0004 * 10 = 259.8 ≈ 260 cents
  const result = lateFee(invoice, '2025-03-26');

  assert.equal(result, 260);
});

test('lateFee: increases with amount due', () => {
  let smallInvoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });

  let largeInvoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(smallInvoiceResult.ok, true);
  assert.equal(largeInvoiceResult.ok, true);

  const smallInvoice = issueInvoice(smallInvoiceResult.value, []).value;
  const largeInvoice = issueInvoice(largeInvoiceResult.value, ['2025-0001']).value;

  const smallFee = lateFee(smallInvoice, '2025-03-26');
  const largeFee = lateFee(largeInvoice, '2025-03-26');

  assert(largeFee > smallFee);
});

test('lateFee: increases linearly with days overdue', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  const fee5Days = lateFee(invoice, '2025-03-21');  // 5 days overdue
  const fee10Days = lateFee(invoice, '2025-03-26'); // 10 days overdue

  assert.equal(fee10Days, fee5Days * 2);
});

test('lateFee: handles invoice with discount', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  // Total after discount: 85500 base + 17955 VAT = 103455
  // 10 days overdue: 103455 * 0.0004 * 10 = 413.82 ≈ 414 cents
  const result = lateFee(invoice, '2025-03-26');

  assert.equal(result, 414);
});

test('lateFee: rounds fee to nearest cent', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  // STICKER: 50 + VAT (21% = 11) = 61 cents
  // 1 day overdue: 61 * 0.0004 * 1 = 0.0244 ≈ 0 cents (rounds down)
  const result = lateFee(invoice, '2025-03-17');

  assert.equal(result, 0);
});

test('lateFee: works with larger day counts', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  // Due date is 2025-03-16, check 100 days later
  // Fee: 114950 * 0.0004 * 100 = 4598 cents
  const result = lateFee(invoice, '2025-06-24');

  assert.equal(result, 4598);
});

test('lateFee: returns integer (cents)', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  const result = lateFee(invoice, '2025-03-26');

  assert.equal(typeof result, 'number');
  assert.equal(result, Math.floor(result));
});
EOF

